// STM32 startup code pattern (startup_stm32.c)
void Default_Handler() {
    while(1);  // Infinite loop trap
}

// Weak aliases for all interrupt handlers
void __attribute__((weak, alias("Default_Handler")))
    USART1_IRQHandler(void);

void __attribute__((weak, alias("Default_Handler")))
    TIM2_IRQHandler(void);

// User code (main.c) - overrides with strong symbol
void USART1_IRQHandler(void) {
    // Custom UART interrupt handling
    // This strong symbol replaces the weak default
}

// Memory hook example
__attribute__((weak))
void* malloc_hook(size_t size) {
    return NULL;  // Default: no hook
}

void* malloc(size_t size) {
    void *result = malloc_hook(size);
    if (result) return result;
    return real_malloc(size);
}

// User provides strong override for debugging:
void* malloc_hook(size_t size) {
    log_allocation(size);
    return NULL;  // Continue to real malloc
}
